# --------------------------------------------------------------------------


def join(root: str, relpath: str) -> str:
    """把目标根目录和一个相对路径拼成绝对路径。"""
    return os.path.join(root, relpath)


def ignores_case() -> bool:
    """当前平台的文件系统是否不区分文件名大小写。"""
    return os.name == "nt"


def path_key(relpath: str) -> str:
    """把相对路径规整成用于比较的键。

    目标平台的文件系统如何认定“两个路径写的是同一个东西”，由本函数
    决定；调用方不应自己再做字符串拼比较。在不区分大小写的文件系统上
    （Windows/NTFS），只有大小写不同的两个路径会得到同一个键。
    """
    normalized = relpath.replace("/", os.sep)
    if os.altsep:
        normalized = normalized.replace(os.altsep, os.sep)
    if ignores_case():
        normalized = os.path.normcase(normalized)
    return normalized


def list_entries(root: str) -> Dict[str, str]:
    """列出目录树中的所有普通文件。

    返回 ``{相对路径: 绝对路径}``；``root`` 不存在时返回空字典。
    """
    entries: Dict[str, str] = {}
    if not os.path.isdir(root):
        return entries
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            full = os.path.join(dirpath, name)
            entries[os.path.relpath(full, root)] = full
    return entries


# --------------------------------------------------------------------------
# “内容是否变化”的判定
# --------------------------------------------------------------------------


def stat_signature(path: str) -> Optional[Tuple[int, int]]:
    """返回 ``(大小, 修改时间)`` 元数据签名；读取失败时返回 ``None``。

    元数据相同**不代表**内容相同——上游工具会就地改写文件并把修改时间戳
    原样保留，所以“要不要更新”必须用 :func:`content_signature` 判定。
    """
    try:
        info = os.stat(path)
    except OSError:
        return None
    return (info.st_size, info.st_mtime_ns)


def _hash_file(path: str) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(_CHUNK_SIZE), b""):
            digest.update(chunk)
    return digest.hexdigest()


def content_signature(path: str) -> Optional[Tuple[int, str]]:
    """返回用于“内容是否变化”判定的签名：``(大小, 内容摘要)``。

    读取失败时返回 ``None``。
    """
    try:
        size = os.path.getsize(path)
        checksum = _hash_file(path)
    except OSError:
        return None
    return (size, checksum)


def same_content(source: str, target: str) -> bool:
    """两个路径上的文件内容是否完全一致。"""
    source_stat = stat_signature(source)
    target_stat = stat_signature(target)
    if source_stat is None or target_stat is None:
        return False
    if source_stat[0] != target_stat[0]:
        return False  # 大小不同，内容必然不同，不必再读一遍
    source_signature = content_signature(source)
    target_signature = content_signature(target)
    if source_signature is None or target_signature is None:
        return False
    return source_signature == target_signature


# --------------------------------------------------------------------------
# 只读属性
# --------------------------------------------------------------------------


def is_readonly(path: str) -> bool:
    """路径是否带有只读属性。"""
    try:
        info = os.stat(path)
    except OSError:
        return False
    if getattr(info, "st_file_attributes", 0) & _READONLY_ATTR:
        return True
    return not bool(info.st_mode & stat.S_IWRITE)


def clear_readonly(path: str) -> bool:
    """去掉 ``path`` 的只读属性，确实去掉了才返回 ``True``。

    路径不存在或改不动属性时返回 ``False``，不抛异常——调用方只是在重试
    之前顺手试一下。
    """
    if not path or not is_readonly(path):
        return False
    try:
        info = os.stat(path)
        os.chmod(path, info.st_mode | stat.S_IWRITE | stat.S_IWUSR)
    except OSError:
        return False
    return not is_readonly(path)


def _is_permission_error(exc: BaseException) -> bool:
    winerror = getattr(exc, "winerror", None)
    if winerror in _LOCKED_WINERRORS or winerror in _DENIED_WINERRORS:
        return True
    return getattr(exc, "errno", None) in _PERMISSION_ERRNOS


def _translate(path: str, exc: OSError) -> Exception:
    """把“去掉只读属性也没用”的权限错误翻译成 wsync 的领域异常。

    走到这里说明只读属性已经处理过了，剩下的权限错误基本上就是条目被别的
    进程占用（Windows 上以 WinError 5 / 32 报告）。
    """
    if getattr(exc, "winerror", None) in _LOCKED_WINERRORS:
        return TargetInUseError(str(exc))
    if isinstance(exc, PermissionError) and not is_readonly(path):
        return TargetInUseError(str(exc))
    return exc


def _with_readonly_retry(path: str, operation) -> None:
    """执行 ``operation(path)``，撞上权限错误就去掉只读属性后重试。

    依次尝试：原样执行 → 去掉自身只读属性 → 去掉父目录只读属性。都不行才
    把错误抛出去，交给上层记成失败条目。
    """
    attempts = 0
    while True:
        try:
            operation(path)
            return
        except OSError as exc:
            if not _is_permission_error(exc):
                raise
            if not os.path.lexists(path):
                return  # 已经不在了，等价于成功
            if attempts >= 2:
                raise _translate(path, exc) from exc
            if attempts == 0:
                clear_readonly(path)
            else:
                parent = os.path.dirname(path)
                if not parent or not clear_readonly(parent):
                    raise _translate(path, exc) from exc
            attempts += 1


# --------------------------------------------------------------------------
# 删除
# --------------------------------------------------------------------------


def _remove(path: str) -> None:
    if _is_real_dir(path):
        os.rmdir(path)
    else:
        os.remove(path)


def _is_real_dir(path: str) -> bool:
    return os.path.isdir(path) and not os.path.islink(path)


def _remove_dir(path: str) -> None:
    _with_readonly_retry(path, _remove)


def remove_file(path: str) -> None:
    """删除单个文件。

    * 文件本来就不存在 → 视为已删除（可能已被同一次同步里的冲突清理消化）；
    * 文件带只读属性 → 去掉只读属性再删；
    * 路径上是一棵目录 → **不动它**；
    * 被别的进程占用 → 抛 :class:`TargetInUseError`，由上层记成失败条目。

    最后一条在不区分大小写的文件系统上很关键：源里是目录 ``Data``、目标里
    是文件 ``data`` 时，计划中的 ``delete data`` 会先被建目录的清理吃掉，等
    真正轮到这条 delete 时，``data`` 指向的已经是刚建好的目录，顺手删掉就会
    把整棵新目录毁掉。删除只针对文件，目录交给 :func:`remove_tree` 与
    :func:`prune_empty_dirs`。
    """
    if not os.path.lexists(path):
        return
    if _is_real_dir(path):
        return
    _with_readonly_retry(path, _remove)


def _collect(failures: List[BaseException], path: str) -> None:
    try:
        _with_readonly_retry(path, _remove)
    except (OSError, SyncError) as exc:
        failures.append(exc)


def remove_tree(path: str) -> None:
    """递归删除一棵目录树。

    树里的只读文件、只读子目录都会先去掉只读属性再删；确实删不掉的条目
    （例如被占用）不会让遍历半途而废，第一个错误在最后抛给上层。
    """
    if not os.path.lexists(path):
        return
    if not _is_real_dir(path):
        _with_readonly_retry(path, _remove)
        return

    failures: List[BaseException] = []
    for dirpath, dirnames, filenames in os.walk(path, topdown=False):
        for name in filenames:
            _collect(failures, os.path.join(dirpath, name))
        for name in dirnames:
            child = os.path.join(dirpath, name)
            # 指向目录的链接不会被 os.walk 展开，这里按文件删掉
            if os.path.islink(child):
                _collect(failures, child)
        try:
            _remove_dir(dirpath)
        except (OSError, SyncError) as exc:
            failures.append(exc)
    if failures:
        raise failures[0]


def prune_empty_dirs(root: str) -> None:
    """自底向上删除目标树中的空目录（不含 ``root`` 自身）。

    只剩只读属性的空目录同样会被清掉；确实删不掉的（例如被占用）保持原样，
    不影响其它目录的清理。
    """
    root = os.path.abspath(root)
    for dirpath, _dirnames, _filenames in os.walk(root, topdown=False):
        if os.path.abspath(dirpath) == root:
            continue
        try:
            if os.listdir(dirpath):
                continue
            _remove_dir(dirpath)
        except (OSError, SyncError):
            continue


# --------------------------------------------------------------------------
# 创建 / 覆盖
# --------------------------------------------------------------------------


def _make_dir(path: str) -> None:
    try:
        os.mkdir(path)
    except FileExistsError:
        if not os.path.isdir(path):
            raise
    except OSError as exc:
        if not _is_permission_error(exc):
            raise
        clear_readonly(path)
        parent = os.path.dirname(path)
        if parent:
            clear_readonly(parent)
        try:
            os.mkdir(path)
        except FileExistsError:
            if not os.path.isdir(path):
                raise
        except OSError as retry_exc:
            if not _is_permission_error(retry_exc):
                raise
            raise _translate(path, retry_exc) from retry_exc


def _ensure_dir(path: str) -> None:
    """确保 ``path`` 是一个目录；挡在同一条路径上的文件会被清掉。"""
    if os.path.isdir(path):
        return
    parent = os.path.dirname(path)
    if parent and parent != path:
        _ensure_dir(parent)
    if os.path.lexists(path) and not _is_real_dir(path):
        # 源在这里需要目录，目标却放着一个同名文件（可能只是大小写不同）。
        # 只清掉构成冲突的这一条路径，其它条目不受影响。
        remove_file(path)
    _make_dir(path)


def ensure_parent_dir(path: str) -> None:
    """确保 ``path`` 的上级目录都存在，必要时让占位的文件“让位”。"""
    parent = os.path.dirname(path)
    if parent:
        _ensure_dir(parent)


def _open_for_write(path: str):
    try:
        return open(path, "wb")
    except OSError as exc:
        if not _is_permission_error(exc):
            raise
        clear_readonly(path)
        parent = os.path.dirname(path)
        if parent:
            clear_readonly(parent)
        try:
            return open(path, "wb")
        except OSError as retry_exc:
            if not _is_permission_error(retry_exc):
                raise
            raise _translate(path, retry_exc) from retry_exc


def _clear_way_for_file(target: str) -> None:
    """把 ``target`` 这条路径腾出来，好让一个文件落在上面。"""
    if _is_real_dir(target):
        # 源里是文件、目标里是一整棵同名目录：整棵目录都已经过期
        remove_tree(target)
    elif os.path.lexists(target):
        clear_readonly(target)


def _replace(temp_path: str, target: str) -> None:
    """把写好的临时文件原子替换到 ``target`` 上。"""
    if os.path.lexists(target):
        clear_readonly(target)
    try:
        os.replace(temp_path, target)
    except OSError as exc:
        if not _is_permission_error(exc):
            raise
        # 只读属性会挡住替换，去掉之后再试一次
        clear_readonly(target)
        try:
            os.replace(temp_path, target)
        except OSError as retry_exc:
            if not _is_permission_error(retry_exc):
                raise
            raise _translate(target, retry_exc) from retry_exc


def _temp_sibling(target: str) -> str:
    return "{0}.wsync-tmp-{1}-{2}".format(target, os.getpid(), next(_TEMP_COUNTER))


def _utime(path: str, stamp: Tuple[int, int]) -> None:
    try:
        os.utime(path, ns=stamp)
    except OSError as exc:
        if not _is_permission_error(exc):
            raise
        clear_readonly(path)
        try:
            os.utime(path, ns=stamp)
        except OSError as retry_exc:
            if not _is_permission_error(retry_exc):
                raise
            raise _translate(path, retry_exc) from retry_exc


def copy_times(source: str, target: str) -> None:
    """把 ``source`` 的访问/修改时间复制到 ``target``。

    同步写完文件之后必须保留源的时间戳，否则目标看起来永远“变了”，下一次
    同步会重复做无谓的动作。
    """
    info = os.stat(source)
    _utime(target, (info.st_atime_ns, info.st_mtime_ns))


def align_times(source: str, target: str) -> bool:
    """尽力把 ``target`` 的时间戳对齐到 ``source``，失败返回 ``False``。

    用于内容一致、本来不需要动的条目：不记任何动作，只是把时间戳补齐，让
    目标成为源的忠实镜像。
    """
    try:
        info = os.stat(source)
        _utime(target, (info.st_atime_ns, info.st_mtime_ns))
    except (OSError, SyncError):
        return False
    return True


def copy_file(source: str, target: str) -> None:
    """把 ``source`` 的内容写到 ``target``，必要时创建父目录。

    顺带处理 Windows 目标树上的常见状态：

    * 缺失的父目录自动创建；父目录的位置被一个同名文件占住时，先把那个
      文件清掉（只动真正构成冲突的那条路径）；
    * ``target`` 上是一棵目录时整棵删掉，是只读文件时去掉只读属性；
    * 内容先写进同目录的临时文件，再原子替换到 ``target``：目标被占用时
      替换会失败，原文件保持原样，不会留下写了一半的残骸；
    * 替换前把源文件的修改时间带到内容上。
    """
    ensure_parent_dir(target)
    _clear_way_for_file(target)
    temp_path = _temp_sibling(target)
    try:
        with open(source, "rb") as src_handle:
            with _open_for_write(temp_path) as dst_handle:
                shutil.copyfileobj(src_handle, dst_handle, length=_CHUNK_SIZE)
        copy_times(source, temp_path)
        _replace(temp_path, target)
    finally:
        _discard(temp_path)


def _discard(path: str) -> None:
    """尽力清掉临时文件，清不掉也不影响主流程。"""
    try:
        if os.path.lexists(path):
            _with_readonly_retry(path, _remove)
    except (OSError, SyncError):
        pass

observation:
"""执行同步计划。

单个条目失败（目标文件被业务程序占用、ACL 拒绝访问……）不允许中断整次
同步：失败被记进 :attr:`SyncResult.failed`，其余条目照常处理。只读属性属于
可以自动修复的情况，在 :mod:`wsync.fsops` 里就地解决，不会变成失败条目。
"""

from __future__ import annotations

import os
from dataclasses import dataclass, field
from typing import Dict, List

from . import fsops
from .errors import SyncError
from .planner import CREATE, DELETE, KEEP, UPDATE, PlanEntry, build_plan


@dataclass
class SyncResult:
    """一次镜像同步的结果。

    ``created`` / ``updated`` / ``deleted`` / ``kept`` 记录已完成的相对
    路径；``failed`` 记录没有完成的条目，每一项形如::

        {"action": "delete", "relpath": "logs/app.old", "error": "..."}
    """

    created: List[str] = field(default_factory=list)
    updated: List[str] = field(default_factory=list)
    deleted: List[str] = field(default_factory=list)
    kept: List[str] = field(default_factory=list)
    failed: List[Dict[str, str]] = field(default_factory=list)

    @property
    def ok(self) -> bool:
        """没有任何条目失败时为 ``True``。"""
        return not self.failed


def _apply(entry: PlanEntry) -> None:
    if entry.action in (CREATE, UPDATE):
        fsops.copy_file(entry.source, entry.target)
    elif entry.action == DELETE:
        fsops.remove_file(entry.target)


def _record(result: SyncResult, action: str, relpath: str) -> None:
    if action == CREATE:
        result.created.append(relpath)
    elif action == UPDATE:
        result.updated.append(relpath)
    elif action == DELETE:
        result.deleted.append(relpath)


def _record_failure(result: SyncResult, entry: PlanEntry, error: BaseException) -> None:
    message = str(error).strip() or error.__class__.__name__
    result.failed.append(
        {"action": entry.action, "relpath": entry.relpath, "error": message}
    )


def sync_tree(source_root: str, target_root: str, dry_run: bool = False) -> SyncResult:
    """把 ``source_root`` 镜像同步到 ``target_root``。"""
    source_root = os.path.abspath(source_root)
    target_root = os.path.abspath(target_root)

    if not dry_run:
        os.makedirs(target_root, exist_ok=True)

    plan = build_plan(source_root, target_root)
    result = SyncResult()

    for entry in plan.entries:
        if entry.action == KEEP:
            # 内容一致就不算动作；只把时间戳对齐，保证目标是源的忠实镜像，
            # 也保证下一次同步依然什么都不会做。
            if not dry_run:
                fsops.align_times(entry.source, entry.target)
            result.kept.append(entry.relpath)
            continue
        if dry_run:
            _record(result, entry.action, entry.relpath)
            continue
        try:
            _apply(entry)
        except (OSError, SyncError) as exc:
            _record_failure(result, entry, exc)
            continue
        _record(result, entry.action, entry.relpath)

    if not dry_run:
        fsops.prune_empty_dirs(target_root)

    return result
